window.AUTH=window.AUTH||{};window.AUTH["23-21"]={"d":"23-21","id":"2023/23-21","n":"Harrow v. Department of Defense","briefs":[{"k":"petitioner","label":"Brief of petitioner Stuart R. Harrow","date":"2024-01-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-21/295636/20240112132428486_1%20%20Merits%20Brief%20Opening4%20-%20FINAL.pdf","side":"pet","n":45},{"k":"respondent","label":"Brief of respondent Department of Defense","date":"2024-02-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-21/300440/20240212193041096_23-21bsUnitedStates.pdf","side":"res","n":127},{"k":"reply","label":"Reply of petitioner Stuart R. Harrow","date":"2024-03-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-21/302883/20240312140405433_HARROW%20-%20Reply%20Brief%20for%20Petitioner.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us2r23_khlp.pdf","tr":true,"items":[{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"op":2,"ar":3,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"0":"1, 12, 22","1":"36, 40"}},{"t":"case","label":"Boechler v. Comm’r","cite":"596 U.S. 199","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/199/","sc":1,"op":5,"sum":"Holding statutory language providing that a “person may, within 30 days of a determination under this section, petition the Tax Court for review of such determination” to be “an ordinary, nonjurisdictional deadline”.","sumSrc":"brief:0","by":{"0":"11, 12, 13, 15, 18","2":"14"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"op":5,"ar":2,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"0":"6, 7, 19","1":"24, 28, 33, 39, 42","2":"12–14, 19"}},{"t":"case","label":"Casillas v. Dep’t of Veterans Affs.","cite":"2023 WL 2029130","y":2023,"court":"Fed. Cir. Feb. 16","by":{"0":"7–8"}},{"t":"case","label":"Castillejos v. Off. of Pers. Mgmt.","cite":"2023 WL 2808067","y":2023,"court":"Fed. Cir. Apr. 6","by":{"0":"7"}},{"t":"case","label":"Edwards v. Off. of Pers. Mgmt.","cite":"2023 WL 2641135","y":2023,"court":"Fed. Cir. Mar. 27","by":{"0":"7"}},{"t":"case","label":"Fed. Educ. Ass’n—Stateside Region v. Dep’t of Def., Domestic Dependents Elementary & Secondary Schs.","cite":"898 F.3d 1222","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/898/1222/","by":{"0":"17","1":"22"}},{"t":"case","label":"Fedora v. MSPB","cite":"848 F.3d 1013","y":2017,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/848/1013/","by":{"0":"6, 7, 9","1":"9, 10, 22","2":"19"}},{"t":"case","label":"Fedora v. MSPB","cite":"868 F.3d 1336","y":2017,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/868/1336/","sum":"Reasoning that Irwin’s presumption of equitable tolling applies to Section 7703(b)(1)(A)’s deadline.","sumSrc":"brief:2","by":{"0":"7","2":"20"}},{"t":"case","label":"Fort Bend Cnty. v. Davis","cite":"139 S. Ct. 1843","y":2019,"id":"2018/18-525","sc":1,"ar":1,"sum":"The charge-filing precondition to suit set out in Title VII of the Civil Rights Act of 1964 is not a jurisdictional requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14, 15, 16, 19, 22","1":"17, 30, 31, 34, 37","2":"6–7, 12–13, 16"}},{"t":"case","label":"Gaddy v. Dep’t of the Navy","cite":"100 M.S.P.R. 485","y":2005,"url":"https://www.courtlistener.com/c/M.S.P.R./100/485/","by":{"0":"5"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"sum":"The Court held that a prisoner who does not seek review in a state’s highest court faces final judgment for the purposes of Section 2244(d)(1)(A) upon “expiration of the time for seeking such review.”","sumSrc":"Oyez","by":{"0":"14, 15, 17","1":"30, 37","2":"4–7"}},{"t":"case","label":"Harrow v. Dep’t of Def. No. 22-2254","cite":"2023 WL 1987934","y":2023,"court":"Fed. Cir. Feb. 14","by":{"0":"2, 8"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"op":2,"ar":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"11, 12, 13, 16, 20, 21, 22","1":"25, 37-40, 41","2":"12, 20"}},{"t":"case","label":"Hobson v. Dep’t of Def.","cite":"2023 WL 3033467","y":2023,"court":"Fed. Cir. Apr. 21","by":{"0":"7"}},{"t":"case","label":"Irwin v. Dep’t of Veterans Affs.","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"ar":1,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"0":"6–7","1":"26, 43","2":"20"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"ar":1,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"0":"21","1":"14, 19, 22, 27, 28"}},{"t":"case","label":"Kloeckner v. Solis","cite":"568 U.S. 41","y":2012,"id":"2012/11-184","sc":1,"ar":1,"sum":"The Court found that the district court, rather than the Court of Appeals, has jurisdiction over \"mixed\" cases that have been dismissed by the Merit Systems Protection Board.","sumSrc":"Oyez","by":{"0":"18, 19, 20","1":"3, 18, 34"}},{"t":"case","label":"Lacy v. Dep’t of the Navy","cite":"78 M.S.P.R. 434","y":1998,"url":"https://www.courtlistener.com/c/M.S.P.R./78/434/","by":{"0":"5"}},{"t":"case","label":"Lindahl v. Off. of Pers. Mgmt.","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"op":3,"ar":6,"sum":"The Office of Personnel Management (OPM) \"determine[s] questions of disability and dependency\" in administering the Federal Government's disability retirement program. 5 U. S. C. § 8347(c). Its \"decisions... concerning these matters are final and conclusive and are not subject to review,\" ibid., except to the extent that administrative review by the Merit Systems Protection Board (MSPB) is provided by §8347(d)(1). …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 22, 23, 24","1":"3, 4, 11, 19-21, 27, 28","2":"1, 10–11"}},{"t":"case","label":"MOAC Mall Holdings LLC v. Transform HoldCo LLC","cite":"598 U.S. 288","y":2023,"id":"2022/21-1270","sc":1,"sum":"Section 363(m) of the Bankruptcy Code—which restricts the effects of certain successful appeals of judicially authorized sales or leases of bankruptcy-estate property—is not a jurisdictional provision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"11, 12","1":"13, 32, 37, 40","2":"10, 14, 20"}},{"t":"case","label":"Musacchio v. United States","cite":"577 U.S. 237","y":2016,"id":"2015/14-1095","sc":1,"sum":"The Court determined that the law of the case doctrine does not require that the sufficiency of evidence be measured against the elements laid out in the jury instructions when those elements require the government to prove more than the statute requires and the government did not object at trial. The Court also determined that a statute of limitations defense that is not raised at trial is not reviewable on appeal.","sumSrc":"Oyez","by":{"0":"12, 13","1":"23, 26, 37"}},{"t":"case","label":"Novilla v. Dep’t of Agric.","cite":"2023 WL 2321985","y":2023,"court":"Fed. Cir. Mar. 2","by":{"0":"7"}},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"sum":"The Court held that the registration requirement of Section 411(a) of the Copyright Act is a precondition to filing a copyright infringement claim.","sumSrc":"Oyez","by":{"0":"10, 13, 14, 15, 19","1":"14, 23, 24, 34, 37, 41","2":"14, 20"}},{"t":"case","label":"Robinson v. Dep’t of Homeland Sec. Off. of the Inspector Gen.","cite":"71 F.4th 51","y":2023,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/71/51/","sum":"Holding the deadline in Section 7703(b)(2) to be nonjurisdictional.","sumSrc":"brief:0","by":{"0":"19"}},{"t":"case","label":"Santos-Zacaria v. Garland","cite":"598 U.S. 411","y":2023,"id":"2022/21-1436","sc":1,"ar":7,"sum":"Title 8 U. S. C. §1252(d)(1)—which requires noncitizens to “exhaus[t] all administrative remedies . . . as of right” before challenging a Board of Immigration Appeals final order of removal in federal court—is not a jurisdictional provision and does not require noncitizens to request discretionary forms of review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"9, 10, 12, 13, 22, 24","1":"36, 40","2":"7, 10–11, 14, 16, 18"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"op":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"0":"12, 14, 17, 19","1":"26","2":"19"}},{"t":"case","label":"United States v. Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"op":10,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"0":"10, 12, 13, 14, 15","1":"26, 37, 39, 44"}},{"t":"case","label":"Wilkins v. United States","cite":"598 U.S. 152","y":2023,"id":"2022/21-1164","sc":1,"ar":1,"sum":"The Quiet Title Act’s 12-year statute of limitations, 28 U. S. C. §2409a(g), is a nonjurisdictional claims-processing rule.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"9, 10, 11, 21, 22, 24","1":"13, 19, 21, 26, 28, 37, 40","2":"11, 13–14"}},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"sum":"In 1970, the union then representing flight attendants employed by respondent Trans World Airlines, Inc. (TWA), brought a federal-court class action alleging that TWA practiced unlawful sex discrimination in violation of Title VII of the Civil Rights Act of 1964 by its policy of grounding all female flight attendants who became mothers while their male counterparts who became fathers were permitted to continue …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"usc","label":"5 U.S.C. § 7701","url":"https://www.law.cornell.edu/uscode/text/5/7701","subs":["(a)","(a)(1)","(a)(2)","(b)(1)","(e)(1)"],"stext":{"head":"§7701. Appellate procedures","paras":[[0,"(a) An employee, or applicant for employment, may submit an appeal to the Merit Systems Protection Board from any action which is appealable to the Board under any law, rule, or regulation. An appellant shall have the right—"],[1,"(1) to a hearing for which a transcript will be kept; and"],[1,"(2) to be represented by an attorney or other representative."],[0,"Appeals shall be processed in accordance with regulations prescribed by the Board."],[0,"(b)(1) The Board may hear any case appealed to it or may refer the case to an administrative law judge appointed under section 3105 of this title or other employee of the Board designated by the Board to hear such cases, except that in any case involving a removal from the service, the case shall be heard by the Board, an employee experienced in hearing appeals, or an administrative law judge. The Board, administrative law judge, or other employee (as the case may be) shall make a decision after receipt of the written representations of the parties to the appeal and after opportunity for a hearing under subsection (a)(1) of this section. A copy of the decision shall be furnished to each party to the appeal and to the Office of Personnel Management."],[0,"(2)(A) If an employee or applicant for employment is the prevailing party in an appeal under this subsection, the employee or applicant shall be granted the relief provided in the decision effective upon the making of the decision, and remaining in effect pending the outcome of any petition for review under subsection (e), unless—"],[1,"(i) the deciding official determines that the granting of such relief is not appropriate; or"],[1,"(ii)(I) the relief granted in the decision provides that such employee or applicant shall return or be present at the place of employment during the period pending the outcome of any petition for review under subsection (e); and"],[1,"(II) the employing agency, subject to the provisions of subparagraph (B), determines that the return or presence of such employee or applicant is unduly disruptive to the work environment."],[0,"(B) If an agency makes a determination under subparagraph (A)(ii)(II) that prevents the return or presence of an employee at the place of employment, such employee shall receive pay, compensation, and all other benefits as terms and conditions of employment during the period pending the outcome of any petition for review under subsection (e)."],[0,"(C) Nothing in the provisions of this paragraph may be construed to require any award of back pay or attorney fees be paid before the decision is final."],[0,"(3) With respect to an appeal from an adverse action covered by subchapter V of chapter 75, authority to mitigate the personnel action involved shall be available, subject to the same standards as would apply in an appeal involving an action covered by subchapter II of chapter 75 with respect to which mitigation authority under this section exists."],[0,"(c)(1) Subject to paragraph (2) of this subsection, the decision of the agency shall be sustained under subsection (b) only if the agency's decision—"],[1,"(A) in the case of an action based on unacceptable performance described in section 4303, is supported by substantial evidence; or"],[1,"(B) in any other case, is supported by a preponderance of the evidence."],[0,"(2) Notwithstanding paragraph (1), the agency's decision may not be sustained under subsection (b) of this section if the employee or applicant for employment—"],[1,"(A) shows harmful error in the application of the agency's procedures in arriving at such decision;"],[1,"(B) shows that the decision was based on any prohibited personnel practice described in section 2302(b) of this title; or"],[1,"(C) shows that the decision was not in accordance with law."],[0,"(d)(1) In any case in which—"],[1,"(A) the interpretation or application of any civil service law, rule, or regulation, under the jurisdiction of the Office of Personnel Management is at issue in any proceeding under this section; and"],[1,"(B) the Director of the Office of Personnel Management is of the opinion that an erroneous decision would have a substantial impact on any civil service law, rule, or regulation under the jurisdiction of the Office;"],[0,"the Director may as a matter of right intervene or otherwise participate in that proceeding before the Board. If the Director exercises his right to participate in a proceeding before the Board, he shall do so as early in the proceeding as practicable. Nothing in this title shall be construed to permit the Office to interfere with the independent decisionmaking of the Merit Systems Protection Board."],[0,"(2) The Board shall promptly notify the Director whenever the interpretation of any civil service law, rule, or regulation under the jurisdiction of the Office is at issue in any proceeding under this section."],[0,"(e)(1) Except as provided in section 7702 of this title, any decision under subsection (b) of this section shall be final unless—"],[1,"(A) a party to the appeal or the Director petitions the Board for review within 30 days after the receipt of the decision; or"],[1,"(B) the Board reopens and reconsiders a case on its own motion."],[0,"The Board, for good cause shown, may extend the 30-day period referred to in subparagraph (A) of this paragraph. One member of the Board may grant a petition or otherwise direct that a decision be reviewed by the full Board. The preceding sentence shall not apply if, by law, a decision of an administrative law judge is required to be acted upon by the Board."],[0,"(2) The Director may petition the Board for a review under paragraph (1) of this subsection only if the Director is of the opinion that the decision is erroneous and will have a substantial impact on any civil service law, rule, or regulation under the jurisdiction of the Office."],[0,"(f) The Board, or an administrative law judge or other employee of the Board designated to hear a case, may—"],[1,"(1) consolidate appeals filed by two or more appellants, or"],[1,"(2) join two or more appeals filed by the same appellant and hear and decide them concurrently,"],[0,"if the deciding official or officials hearing the cases are of the opinion that the action could result in the appeals' being processed more expeditiously and would not adversely affect any party."],[0,"(g)(1) Except as provided in paragraph (2) of this subsection, the Board, or an administrative law judge or other employee of the Board designated to hear a case, may require payment by the agency involved of reasonable attorney fees incurred by an employee or applicant for employment if the employee or applicant is the prevailing party and the Board, administrative law judge, or other employee (as the case may be) determines that payment by the agency is warranted in the interest of justice, including any case in which a prohibited personnel practice was engaged in by the agency or any case in which the agency's action was clearly without merit."],[0,"(2) If an employee or applicant for employment is the prevailing party and the decision is based on a finding of discrimination prohibited under section 2302(b)(1) of this title, the payment of attorney fees shall be in accordance with the standards prescribed under section 706(k) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–5(k))."],[0,"(h) The Board may, by regulation, provide for one or more alternative methods for settling matters subject to the appellate jurisdiction of the Board which shall be applicable at the election of an applicant for employment or of an employee who is not in a unit for which a labor organization is accorded exclusive recognition, and shall be in lieu of other procedures provided for under this section. A decision under such a method shall be final, unless the Board reopens and reconsiders a case at the request of the Office of Personnel Management under subsection (e) of this section."],[0,"(i)(1) Upon the submission of any appeal to the Board under this section, the Board, through reference to such categories of cases, or other means, as it determines appropriate, shall establish and announce publicly the date by which it intends to complete action on the matter. Such date shall assure expeditious consideration of the appeal, consistent with the interests of fairness and other priorities of the Board. If the Board fails to complete action on the appeal by the announced date, and the expected delay will exceed 30 days, the Board shall publicly announce the new date by which it intends to complete action on the appeal."],[0,"(2) Not later than March 1 of each year, the Board shall submit to the Congress a report describing the number of appeals submitted to it during the preceding fiscal year, the number of appeals on which it completed action during that year, and the number of instances during that year in which it failed to conclude a proceeding by the date originally announced, together with an explanation of the reasons therefor."],[0,"(3) The Board shall by rule indicate any other category of significant Board action which the Board determines should be subject to the provisions of this subsection."],[0,"(4) It shall be the duty of the Board, an administrative law judge, or employee designated by the Board to hear any proceeding under this section to expedite to the extent practicable that proceeding."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7701?type=usc&year=mostrecent&link-type=html"},"head":"§7701. Appellate procedures","tname":"Government Organization and Employees","by":{"0":"4, 5","1":"6, 6, 6, 6, 7"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(a)(1)","(b)(1)(1982)","(b)(1)","(b)(1)(A)","(b)(1)(B)","(b)(2)","(d)(1982)","(d)","(d)(2)","(b)"],"stext":{"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","paras":[[0,"(a)(1) Any employee or applicant for employment adversely affected or aggrieved by a final order or decision of the Merit Systems Protection Board may obtain judicial review of the order or decision."],[0,"(2) The Board shall be named respondent in any proceeding brought pursuant to this subsection, unless the employee or applicant for employment seeks review of a final order or decision on the merits on the underlying personnel action or on a request for attorney fees, in which case the agency responsible for taking the personnel action shall be the respondent."],[0,"(b)(1)(A) Except as provided in subparagraph (B) and paragraph (2) of this subsection, a petition to review a final order or final decision of the Board shall be filed in the United States Court of Appeals for the Federal Circuit. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(B) A petition to review a final order or final decision of the Board that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D) shall be filed in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(2) Cases of discrimination subject to the provisions of section 7702 of this title shall be filed under section 717(c) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16(c)), section 15(c) of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 633a(c)), and section 16(b) of the Fair Labor Standards Act of 1938, as amended (29 U.S.C. 216(b)), as applicable. Notwithstanding any other provision of law, any such case filed under any such section must be filed within 30 days after the date the individual filing the case received notice of the judicially reviewable action under such section 7702."],[0,"(c) In any case filed in the United States Court of Appeals for the Federal Circuit, the court shall review the record and hold unlawful and set aside any agency action, findings, or conclusions found to be—"],[1,"(1) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(2) obtained without procedures required by law, rule, or regulation having been followed; or"],[1,"(3) unsupported by substantial evidence;"],[0,"except that in the case of discrimination brought under any section referred to in subsection (b)(2) of this section, the employee or applicant shall have the right to have the facts subject to trial de novo by the reviewing court."],[0,"(d)(1) Except as provided under paragraph (2), this paragraph shall apply to any review obtained by the Director of the Office of Personnel Management. The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the Court of Appeals. The granting of the petition for judicial review shall be at the discretion of the Court of Appeals."],[0,"(2) This paragraph shall apply to any review obtained by the Director of the Office of Personnel Management that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D). The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the court of appeals. The granting of the petition for judicial review shall be at the discretion of the court of appeals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7703?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","tname":"Government Organization and Employees","by":{"0":"1–3, 6, 9–21, 23, 24","1":"3, 3, 3, 3, 3, 3, 3, 37, 37","2":"1–4, 7–11, 16, 18–20, 1–4, 8–10"}},{"t":"usc","label":"5 U.S.C. § 8347","url":"https://www.law.cornell.edu/uscode/text/5/8347","by":{"0":"23"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 1295","url":"https://www.law.cornell.edu/uscode/text/28/1295","subs":["(a)(9)","(a)"],"stext":{"head":"§1295. Jurisdiction of the United States Court of Appeals for the Federal Circuit","paras":[[0,"(a) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from a final decision of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court of the Northern Mariana Islands, in any civil action arising under, or in any civil action in which a party has asserted a compulsory counterclaim arising under, any Act of Congress relating to patents or plant variety protection;"],[1,"(2) of an appeal from a final decision of a district court of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, if the jurisdiction of that court was based, in whole or in part, on section 1346 of this title, except that jurisdiction of an appeal in a case brought in a district court under section 1346(a)(1), 1346(b), 1346(e), or 1346(f) of this title or under section 1346(a)(2) when the claim is founded upon an Act of Congress or a regulation of an executive department providing for internal revenue shall be governed by sections 1291, 1292, and 1294 of this title;"],[1,"(3) of an appeal from a final decision of the United States Court of Federal Claims;"],[1,"(4) of an appeal from a decision of—"],[2,"(A) the Patent Trial and Appeal Board of the United States Patent and Trademark Office with respect to a patent application, derivation proceeding, reexamination, post-grant review, or inter partes review under title 35, at the instance of a party who exercised that party's right to participate in the applicable proceeding before or appeal to the Board, except that an applicant or a party to a derivation proceeding may also have remedy by civil action pursuant to section 145 or 146 of title 35; an appeal under this subparagraph of a decision of the Board with respect to an application or derivation proceeding shall waive the right of such applicant or party to proceed under section 145 or 146 of title 35;"],[2,"(B) the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office or the Trademark Trial and Appeal Board with respect to applications for registration of marks and other proceedings as provided in section 21 of the Trademark Act of 1946 (15 U.S.C. 1071); or"],[2,"(C) a district court to which a case was directed pursuant to section 145, 146, or 154(b) of title 35;"],[1,"(5) of an appeal from a final decision of the United States Court of International Trade;"],[1,"(6) to review the final determinations of the United States International Trade Commission relating to unfair practices in import trade, made under section 337 of the Tariff Act of 1930 (19 U.S.C. 1337);"],[1,"(7) to review, by appeal on questions of law only, findings of the Secretary of Commerce under U.S. note 6 to subchapter X of chapter 98 of the Harmonized Tariff Schedule of the United States (relating to importation of instruments or apparatus);"],[1,"(8) of an appeal under section 71 of the Plant Variety Protection Act (7 U.S.C. 2461);"],[1,"(9) of an appeal from a final order or final decision of the Merit Systems Protection Board, pursuant to sections 7703(b)(1) and 7703(d) of title 5;"],[1,"(10) of an appeal from a final decision of an agency board of contract appeals pursuant to section 7107(a)(1) of title 41;"],[1,"(11) of an appeal under section 211 of the Economic Stabilization Act of 1970;"],[1,"(12) of an appeal under section 5 of the Emergency Petroleum Allocation Act of 1973;"],[1,"(13) of an appeal under section 506(c) of the Natural Gas Policy Act of 1978; and"],[1,"(14) of an appeal under section 523 of the Energy Policy and Conservation Act."],[0,"(b) The head of any executive department or agency may, with the approval of the Attorney General, refer to the Court of Appeals for the Federal Circuit for judicial review any final decision rendered by a board of contract appeals pursuant to the terms of any contract with the United States awarded by that department or agency which the head of such department or agency has concluded is not entitled to finality pursuant to the review standards specified in section 7107(b) of title 41. The head of each executive department or agency shall make any referral under this section within one hundred and twenty days after the receipt of a copy of the final appeal decision."],[0,"(c) The Court of Appeals for the Federal Circuit shall review the matter referred in accordance with the standards specified in section 7107(b) of title 41. The court shall proceed with judicial review on the administrative record made before the board of contract appeals on matters so referred as in other cases pending in such court, shall determine the issue of finality of the appeal decision, and shall, if appropriate, render judgment thereon, or remand the matter to any administrative or executive body or official with such direction as it may deem proper and just."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1295?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1295. Jurisdiction of the United States Court of Appeals for the Federal Circuit","tname":"Judiciary and Judicial Procedure","by":{"0":"14, 15, 16, 17, 23","1":"34, 36, 37","2":"1–4, 7–10"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","by":{"0":"15"}},{"t":"usc","label":"38 U.S.C. § 7266","url":"https://www.law.cornell.edu/uscode/text/38/7266","subs":["(a)"],"stext":{"head":"§7266. Notice of appeal","paras":[[0,"(a) In order to obtain review by the Court of Appeals for Veterans Claims of a final decision of the Board of Veterans' Appeals, a person adversely affected by such decision shall file a notice of appeal with the Court within 120 days after the date on which notice of the decision is issued pursuant to section 7104(e) of this title."],[0,"(b) An appellant shall file a notice of appeal under this section by delivering or mailing the notice to the Court."],[0,"(c) A notice of appeal shall be deemed to be received by the Court as follows:"],[1,"(1) On the date of receipt by the Court, if the notice is delivered."],[1,"(2) On the date of the United States Postal Service postmark stamped on the cover in which the notice is posted, if the notice is properly addressed to the Court and is mailed."],[0,"(d) For a notice of appeal mailed to the Court to be deemed to be received under subsection (c)(2) on a particular date, the United States Postal Service postmark on the cover in which the notice is posted must be legible. The Court shall determine the legibility of any such postmark and the Court's determination as to legibility shall be final and not subject to review by any other Court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7266?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7266. Notice of appeal","tname":"Veterans' Benefits","by":{"0":"13","1":"37"}},{"t":"usc","label":"38 U.S.C. § 7292","url":"https://www.law.cornell.edu/uscode/text/38/7292","subs":["(a)"],"stext":{"head":"§7292. Review by United States Court of Appeals for the Federal Circuit","paras":[[0,"(a) After a decision of the United States Court of Appeals for Veterans Claims is entered in a case, any party to the case may obtain a review of the decision with respect to the validity of a decision of the Court on a rule of law or of any statute or regulation (other than a refusal to review the schedule of ratings for disabilities adopted under section 1155 of this title) or any interpretation thereof (other than a determination as to a factual matter) that was relied on by the Court in making the decision. Such a review shall be obtained by filing a notice of appeal with the Court of Appeals for Veterans Claims within the time and in the manner prescribed for appeal to United States courts of appeals from United States district courts."],[0,"(b)(1) When a judge or panel of the Court of Appeals for Veterans Claims, in making an order not otherwise appealable under this section, determines that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that there is in fact a disagreement between the appellant and the Secretary with respect to that question of law and that the ultimate termination of the case may be materially advanced by the immediate consideration of that question, the judge or panel shall notify the chief judge of that determination. Upon receiving such a notification, the chief judge shall certify that such a question is presented, and any party to the case may then petition the Court of Appeals for the Federal Circuit to decide the question. That court may permit an interlocutory appeal to be taken on that question if such a petition is filed with it within 10 days after the certification by the chief judge of the Court of Appeals for Veterans Claims. Neither the application for, nor the granting of, an appeal under this paragraph shall stay proceedings in the Court of Appeals for Veterans Claims, unless a stay is ordered by a judge of the Court of Appeals for Veterans Claims or by the Court of Appeals for the Federal Circuit."],[0,"(2) For purposes of subsections (d) and (e) of this section, an order described in this paragraph shall be treated as a decision of the Court of Appeals for Veterans Claims."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction to review and decide any challenge to the validity of any statute or regulation or any interpretation thereof brought under this section, and to interpret constitutional and statutory provisions, to the extent presented and necessary to a decision. The judgment of such court shall be final subject to review by the Supreme Court upon certiorari, in the manner provided in section 1254 of title 28."],[0,"(d)(1) The Court of Appeals for the Federal Circuit shall decide all relevant questions of law, including interpreting constitutional and statutory provisions. The court shall hold unlawful and set aside any regulation or any interpretation thereof (other than a determination as to a factual matter) that was relied upon in the decision of the Court of Appeals for Veterans Claims that the Court of Appeals for the Federal Circuit finds to be—"],[1,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(B) contrary to constitutional right, power, privilege, or immunity;"],[1,"(C) in excess of statutory jurisdiction, authority, or limitations, or in violation of a statutory right; or"],[1,"(D) without observance of procedure required by law."],[0,"(2) Except to the extent that an appeal under this chapter presents a constitutional issue, the Court of Appeals may not review (A) a challenge to a factual determination, or (B) a challenge to a law or regulation as applied to the facts of a particular case."],[0,"(e)(1) Upon such review, the Court of Appeals for the Federal Circuit shall have power to affirm or, if the decision of the Court of Appeals for Veterans Claims is not in accordance with law, to modify or reverse the decision of the Court of Appeals for Veterans Claims or to remand the matter, as appropriate."],[0,"(2) Rules for review of decisions of the Court of Appeals for Veterans Claims shall be those prescribed by the Supreme Court under section 2072 of title 28."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7292?type=usc&year=mostrecent&link-type=html"},"head":"§7292. Review by United States Court of Appeals for the Federal Circuit","tname":"Veterans' Benefits","by":{"0":"16","1":"32"}},{"t":"law","label":"Civil Service Reform Act, Pub. L. No. 95-454","url":"https://www.govinfo.gov/link/statute/92/1111","by":{"0":"3","1":"27"}},{"t":"reg","label":"5 C.F.R. § 1201.21","url":"https://www.ecfr.gov/current/title-5/section-1201.21","by":{"0":"4"}},{"t":"reg","label":"5 C.F.R. § 1201.22","url":"https://www.ecfr.gov/current/title-5/section-1201.22","by":{"0":"5"}},{"t":"reg","label":"5 C.F.R. § 1201.25","url":"https://www.ecfr.gov/current/title-5/section-1201.25","by":{"0":"5"}},{"t":"reg","label":"5 C.F.R. § 1201.29","url":"https://www.ecfr.gov/current/title-5/section-1201.29","by":{"0":"5"}},{"t":"reg","label":"5 C.F.R. § 1201.56","url":"https://www.ecfr.gov/current/title-5/section-1201.56","by":{"0":"5"}},{"t":"reg","label":"5 C.F.R. § 1201.71","url":"https://www.ecfr.gov/current/title-5/section-1201.71","by":{"0":"5"}},{"t":"case","label":"American Fire & Cas. Co. v. Finn","cite":"341 U.S. 6","y":1951,"id":"scdb/1950-055","sc":1,"sum":"In a suit brought in a Texas court by a resident of that State to recover for a loss by fire, the complaint named as defendants two foreign insurance companies (one of which is the petitioner here) and a resident agent of the companies. The single wrong for which relief was sought was the failure to compensate for the loss, and the three defendants were joined because of uncertainty as to who was liable. After …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Ash v. OPM","cite":"25 F.4th 1009","y":2022,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/25/1009/","by":{"1":"19, 31"}},{"t":"case","label":"Badgerow v. Walters","cite":"596 U.S. 1","y":2022,"id":"2021/20-1143","sc":1,"op":4,"sum":"Federal jurisdiction in a petition to compel arbitration under Section 4 of the Federal Arbitration Act is determined by “looking through” the petition to the jurisdictional basis of the “underlying substantive controversy,” Vaden v. Discover Bank, 556 U. S. 49, 62, but that approach does not apply to petitions to confirm or vacate arbitral awards under Sections 9 and 10 of the FAA.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"35"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"sum":"Pursuant to §523(a)(2)(A) of the Bankruptcy Code, a debtor like Kate Bartenwerfer who is liable for her partner’s fraud cannot discharge that debt in bankruptcy, regardless of her own culpability.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"42"}},{"t":"case","label":"Bender v. Williamsport Area Sch. Dist.","cite":"475 U.S. 534","y":1986,"id":"1985/84-773","sc":1,"sum":"Respondent had no standing to appeal, and therefore the Court of Appeals had no jurisdiction to hear his appeal.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12"}},{"t":"case","label":"Boechler, P.C. v. Commissioner","cite":"596 U.S. 199","y":2022,"id":"2021/20-1472","sc":1,"op":5,"sum":"The 30-day time limit to file a petition for review of a collection due process determination, 26 U. S. C. §6330(d)(1), is a nonjurisdictional deadline subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"11, 13, 14, 17, 26, 30, 38, 39, 43"}},{"t":"case","label":"Boehm v. Foster","cite":"670 F.2d 111","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/670/111/","by":{"1":"27"}},{"t":"case","label":"Bowen v. City of New York","cite":"476 U.S. 467","y":1986,"id":"1985/84-1923","sc":1,"sum":"The Social Security Act provides benefits to disabled persons under two programs administered by the Social Security Administration (SSA): the Social Security Disability Insurance Program (SSD) and the Supplemental Security Income Program (SSI). Regulations for both programs establish a five-step \"sequential evaluation\" process for determining eligibility for benefits. The initial determination of whether an …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Brotherhood of Locomotive Eng’rs v. Federal R.R. Admin.","cite":"972 F.3d 83","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/972/83/","by":{"1":"26"}},{"t":"case","label":"Brown v. Nuclear Regulatory Comm’n","cite":"644 F.3d 726","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/644/726/","by":{"1":"25"}},{"t":"case","label":"California Pub. Employees’ Ret. Sys. v. ANZ Sec., Inc.","cite":"582 U.S. 497","y":2017,"id":"2016/16-373","sc":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"1":"42, 43"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"sum":"The Court found that only tribes under federal jurisdiction at the time of the Indian Reorganization Act of 1934 are subject to taking by the federal government.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Carpenter v. Department of Transp.","cite":"13 F.3d 313","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/13/313/","by":{"1":"26"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Consumers’ Research v. FCC","cite":"67 F.4th 773","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/67/773/","by":{"1":"25"}},{"t":"case","label":"Council Tree Commc’ns, Inc. v. FCC","cite":"503 F.3d 284","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/503/284/","by":{"1":"25"}},{"t":"case","label":"Council Tree Investors, Inc. v. FCC","cite":"739 F.3d 544","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/739/544/","by":{"1":"25"}},{"t":"case","label":"Cyan, Inc. v. Beaver County Emps. Ret. Fund","cite":"583 U.S. 416","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Devine v. White","cite":"697 F.2d 421","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/697/421/","by":{"1":"27"}},{"t":"case","label":"Dodd v. United States","cite":"545 U.S. 353","y":2005,"id":"2004/04-5286","sc":1,"sum":"The Court held that the text of the federal law \"unequivocally\" stated that the one-year limitation period begins to run on the date on which the Court \"initially recongized\" the right, not the date on which that right was made retroactive.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"FEC v. NRA Political Victory Fund","cite":"513 U.S. 88","y":1994,"id":"1994/93-1151","sc":1,"sum":"Petitioner Federal Election Commission (FEC) brought this civil action against respondents seeking to enforce a provision of the Federal Election Campaign Act of 1971 (FECA). The District Court ruled against respondents. The Court of Appeals reversed and entered its judgment on October 22, 1993. Without first seeking or obtaining the Solicitor General's authorization, the FEC filed in its own name a petition for a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Gorss Motels, Inc. v. FCC","cite":"20 F.4th 87","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/20/87/","by":{"1":"25"}},{"t":"case","label":"Hamer v. Neighborhood Hous. Servs. of Chicago","cite":"583 U.S. 17","y":2017,"id":"2017/16-658","sc":1,"op":1,"ar":1,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"1":"24","2":"12, 16, 20"}},{"t":"case","label":"Helsinn Healthcare S.A. v. Teva Pharms. USA, Inc.","cite":"139 S. Ct. 628","y":2019,"id":"2018/17-1229","sc":1,"ar":1,"sum":"The sale of an invention to a third party who is obligated to keep the invention confidential may place the invention “on sale” for purposes of the Leahy-Smith America Invents Act, which bars a person from receiving a patent on an invention that was “in public use, on sale, or otherwise available to the public before the effective filing date of the claimed invention,” 35 U. S. C. §102(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Knowles v. Holly","cite":"513 P.2d 18","y":1973,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/513/18/","by":{"1":"15"}},{"t":"case","label":"Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","cite":"599 U.S. 382","y":2023,"id":"2022/22-227","sc":1,"sum":"The Bankruptcy Code unequivocally abrogates the sovereign immunity of all governments, including federally recognized Indian tribes.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"32"}},{"t":"case","label":"Lewis v. IRS","cite":"691 F.2d 858","y":1982,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/691/858/","by":{"1":"27"}},{"t":"case","label":"Lockerty v. Phillips","cite":"319 U.S. 182","y":1943,"id":"scdb/1942-149","sc":1,"sum":"1. The Emergency Price Control Act of 1942 sets up a procedure whereby any person subject to any regulation or order promulgated under the Act may on \"protest\" of the regulation or order secure its review by the Administrator; and, if the protest is denied, the Act confers on the Emergency Court (and on the Supreme Court upon review of decisions of the Emergency Court) equity jurisdicLOCKERTY v. PHILLIPS. Counsel …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"1":"23"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"1":"42, 43"}},{"t":"case","label":"Matson Navigation Co. v. United States Dep’t of Transp.","cite":"895 F.3d 799","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/895/799/","by":{"1":"25"}},{"t":"case","label":"Monzo v. Department of Transp.","cite":"735 F.2d 1335","y":1984,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/735/1335/","by":{"1":"4, 22"}},{"t":"case","label":"New Orleans Pub. Serv., Inc. v. Council of the City of New Orleans","cite":"491 U.S. 350","y":1989,"id":"1988/88-348","sc":1,"sum":"The District Court erred in abstaining from exercising jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"op":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"15"}},{"t":"case","label":"NLRB Union v. FLRA","cite":"834 F.2d 191","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/834/191/","by":{"1":"26"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"139 S. Ct. 710","y":2019,"id":"2018/17-1094","sc":1,"sum":"Federal Rule of Civil Procedure 23(f), which establishes a 14-day deadline to seek permission to appeal an order granting or denying class certification, is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"42, 43","2":"20"}},{"t":"case","label":"Oja v. Department of the Army","cite":"405 F.3d 1349","y":2005,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/405/1349/","ar":1,"sum":"Finding “no specific authorization for the equitable tolling of section 7703(b)(1)”.","sumSrc":"brief:1","by":{"1":"22, 44"}},{"t":"case","label":"Owner-Operator Indep. Drivers Ass’n v. United States Dep’t of Transp.","cite":"858 F.3d 980","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/858/980/","by":{"1":"25"}},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"ar":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Perry v. MSPB","cite":"582 U.S. 420","y":2017,"url":"https://supreme.justia.com/cases/federal/us/582/420/","sc":1,"by":{"1":"3"}},{"t":"case","label":"Pinat v. OPM","cite":"931 F.2d 1544","y":1991,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/931/1544/","by":{"1":"4, 7, 22"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Ramos v. United States","cite":"683 F.2d 396","y":1982,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/683/396/","by":{"1":"27"}},{"t":"case","label":"SAS Inst. Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Schneider Nat’l Inc. v. ICC","cite":"948 F.2d 338","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/948/338/","by":{"1":"25"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"West Coast Truck Lines, Inc. v. American Indus., Inc.","cite":"893 F.2d 229","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/893/229/","by":{"1":"25"}},{"t":"law","label":"All Circuit Review Act, Pub. L. No. 115-195","url":"https://www.govinfo.gov/link/plaw/115/public/195","by":{"1":"5"}},{"t":"law","label":"regulations, and rules—Continued: All Circuit Review Extension Act, Pub. L. No. 113-170","url":"https://www.govinfo.gov/link/plaw/113/public/170","by":{"1":"5"}},{"t":"law","label":"Pub. L. No. 97-164","url":"https://www.govinfo.gov/link/statute/96/25","by":{"1":"2"}},{"t":"law","label":"Federal Employees Life Insurance Improvement Act, Pub. L. No. 105-311","url":"https://www.govinfo.gov/link/plaw/105/public/311","by":{"1":"4, 22"}},{"t":"law","label":"Pub. L. No. 112-199","url":"https://www.govinfo.gov/link/plaw/112/public/199","by":{"1":"4, 44"}},{"t":"usc","label":"5 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/5/1201","by":{"1":"7"}},{"t":"usc","label":"5 U.S.C. § 1204","url":"https://www.law.cornell.edu/uscode/text/5/1204","by":{"1":"3"}},{"t":"usc","label":"5 U.S.C. § 7511","url":"https://www.law.cornell.edu/uscode/text/5/7511","subs":["(a)(1)(A)","(a)(5)"],"by":{"1":"6, 6"}},{"t":"usc","label":"5 U.S.C. § 7512","url":"https://www.law.cornell.edu/uscode/text/5/7512","subs":["(5)"],"by":{"1":"6"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","subs":["(a)"],"by":{"1":"6"}},{"t":"usc","label":"11 U.S.C. § 363","url":"https://www.law.cornell.edu/uscode/text/11/363","subs":["(m)"],"by":{"1":"37"}},{"t":"usc","label":"17 U.S.C. § 411","url":"https://www.law.cornell.edu/uscode/text/17/411","subs":["(a)"],"by":{"1":"37"}},{"t":"usc","label":"18 U.S.C. § 3231","url":"https://www.law.cornell.edu/uscode/text/18/3231","by":{"1":"37"}},{"t":"usc","label":"18 U.S.C. § 3282","url":"https://www.law.cornell.edu/uscode/text/18/3282","subs":["(a)"],"by":{"1":"37"}},{"t":"usc","label":"26 U.S.C. § 6330","url":"https://www.law.cornell.edu/uscode/text/26/6330","subs":["(d)(1)"],"by":{"1":"38"}},{"t":"usc","label":"28 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/28/157","by":{"1":"37"}},{"t":"usc","label":"28 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/28/158","by":{"1":"37"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"1":"34, 36, 37"}},{"t":"usc","label":"28 U.S.C. § 1334","url":"https://www.law.cornell.edu/uscode/text/28/1334","by":{"1":"37"}},{"t":"usc","label":"28 U.S.C. § 1338","url":"https://www.law.cornell.edu/uscode/text/28/1338","by":{"1":"37"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(a)(2)(1976)","(b)(1)"],"by":{"1":"27, 37"}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","subs":["(1976)"],"by":{"1":"27"}},{"t":"usc","label":"28 U.S.C. § 2072","url":"https://www.law.cornell.edu/uscode/text/28/2072","by":{"1":"43"}},{"t":"usc","label":"28 U.S.C. § 2074","url":"https://www.law.cornell.edu/uscode/text/28/2074","by":{"1":"43"}},{"t":"usc","label":"28 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/28/2101","subs":["(c)"],"by":{"1":"24"}},{"t":"usc","label":"28 U.S.C. § 2107","url":"https://www.law.cornell.edu/uscode/text/28/2107","by":{"1":"12, 24"}},{"t":"usc","label":"28 U.S.C. § 2253","url":"https://www.law.cornell.edu/uscode/text/28/2253","subs":["(a)","(c)(3)","(c)"],"stext":{"head":"§2253. Appeal","paras":[[0,"(a) In a habeas corpus proceeding or a proceeding under section 2255 before a district judge, the final order shall be subject to review, on appeal, by the court of appeals for the circuit in which the proceeding is held."],[0,"(b) There shall be no right of appeal from a final order in a proceeding to test the validity of a warrant to remove to another district or place for commitment or trial a person charged with a criminal offense against the United States, or to test the validity of such person's detention pending removal proceedings."],[0,"(c)(1) Unless a circuit justice or judge issues a certificate of appealability, an appeal may not be taken to the court of appeals from—"],[1,"(A) the final order in a habeas corpus proceeding in which the detention complained of arises out of process issued by a State court; or"],[1,"(B) the final order in a proceeding under section 2255."],[0,"(2) A certificate of appealability may issue under paragraph (1) only if the applicant has made a substantial showing of the denial of a constitutional right."],[0,"(3) The certificate of appealability under paragraph (1) shall indicate which specific issue or issues satisfy the showing required by paragraph (2)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2253?type=usc&year=mostrecent&link-type=html"},"head":"§2253. Appeal","tname":"Judiciary and Judicial Procedure","by":{"1":"37, 30, 37","2":"4–5"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","by":{"1":"25"}},{"t":"usc","label":"28 U.S.C. § 2344","url":"https://www.law.cornell.edu/uscode/text/28/2344","by":{"1":"25, 27"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(b)"],"stext":{"head":"§2401. Time for commencing action against United States","paras":[[0,"(a) Except as provided by chapter 71 of title 41, every civil action commenced against the United States shall be barred unless the complaint is filed within six years after the right of action first accrues. The action of any person under legal disability or beyond the seas at the time the claim accrues may be commenced within three years after the disability ceases."],[0,"(b) A tort claim against the United States shall be forever barred unless it is presented in writing to the appropriate Federal agency within two years after such claim accrues or unless action is begun within six months after the date of mailing, by certified or registered mail, of notice of final denial of the claim by the agency to which it was presented."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2401?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2401. Time for commencing action against United States","tname":"Judiciary and Judicial Procedure","by":{"1":"37"}},{"t":"usc","label":"28 U.S.C. § 2409a","url":"https://www.law.cornell.edu/uscode/text/28/2409a","subs":["(g)"],"by":{"1":"37"}},{"t":"usc","label":"28 U.S.C. § 2501","url":"https://www.law.cornell.edu/uscode/text/28/2501","by":{"1":"27"}},{"t":"usc","label":"35 U.S.C. § 314","url":"https://www.law.cornell.edu/uscode/text/35/314","subs":["(b)"],"by":{"1":"16"}},{"t":"usc","label":"38 U.S.C. § 7252","url":"https://www.law.cornell.edu/uscode/text/38/7252","subs":["(a)"],"by":{"1":"37"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","subs":["(b)"],"by":{"1":"36"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(e)(1)","(f)"],"stext":{"head":"§2000e–5. Enforcement provisions","paras":[[0,"(a) Power of Commission to prevent unlawful employment practices"],[0,"The Commission is empowered, as hereinafter provided, to prevent any person from engaging in any unlawful employment practice as set forth in section 2000e–2 or 2000e–3 of this title."],[0,"(b) Charges by persons aggrieved or member of Commission of unlawful employment practices by employers, etc.; filing; allegations; notice to respondent; contents of notice; investigation by Commission; contents of charges; prohibition on disclosure of charges; determination of reasonable cause; conference, conciliation, and persuasion for elimination of unlawful practices; prohibition on disclosure of informal endeavors to end unlawful practices; use of evidence in subsequent proceedings; penalties for disclosure of information; time for determination of reasonable cause"],[0,"Whenever a charge is filed by or on behalf of a person claiming to be aggrieved, or by a member of the Commission, alleging that an employer, employment agency, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, has engaged in an unlawful employment practice, the Commission shall serve a notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) on such employer, employment agency, labor organization, or joint labor-management committee (hereinafter referred to as the \"respondent\") within ten days, and shall make an investigation thereof. Charges shall be in writing under oath or affirmation and shall contain such information and be in such form as the Commission requires. Charges shall not be made public by the Commission. If the Commission determines after such investigation that there is not reasonable cause to believe that the charge is true, it shall dismiss the charge and promptly notify the person claiming to be aggrieved and the respondent of its action. In determining whether reasonable cause exists, the Commission shall accord substantial weight to final findings and orders made by State or local authorities in proceedings commenced under State or local law pursuant to the requirements of subsections (c) and (d). If the Commission determines after such investigation that there is reasonable cause to believe that the charge is true, the Commission shall endeavor to eliminate any such alleged unlawful employment practice by informal methods of conference, conciliation, and persuasion. Nothing said or done during and as a part of such informal endeavors may be made public by the Commission, its officers or employees, or used as evidence in a subsequent proceeding without the written consent of the persons concerned. Any person who makes public information in violation of this subsection shall be fined not more than $1,000 or imprisoned for not more than one year, or both. The Commission shall make its determination on reasonable cause as promptly as possible and, so far as practicable, not later than one hundred and twenty days from the filing of the charge or, where applicable under subsection (c) or (d), from the date upon which the Commission is authorized to take action with respect to the charge."],[0,"(c) State or local enforcement proceedings; notification of State or local authority; time for filing charges with Commission; commencement of proceedings"],[0,"In the case of an alleged unlawful employment practice occurring in a State, or political subdivision of a State, which has a State or local law prohibiting the unlawful employment practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, no charge may be filed under subsection (a) 1 by the person aggrieved before the expiration of sixty days after proceedings have been commenced under the State or local law, unless such proceedings have been earlier terminated, provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective date of such State or local law. If any requirement for the commencement of such proceedings is imposed by a State or local authority other than a requirement of the filing of a written and signed statement of the facts upon which the proceeding is based, the proceeding shall be deemed to have been commenced for the purposes of this subsection at the time such statement is sent by registered mail to the appropriate State or local authority."],[0,"(d) State or local enforcement proceedings; notification of State or local authority; time for action on charges by Commission"],[0,"In the case of any charge filed by a member of the Commission alleging an unlawful employment practice occurring in a State or political subdivision of a State which has a State or local law prohibiting the practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, the Commission shall, before taking any action with respect to such charge, notify the appropriate State or local officials and, upon request, afford them a reasonable time, but not less than sixty days (provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective day of such State or local law), unless a shorter period is requested, to act under such State or local law to remedy the practice alleged."],[0,"(e) Time for filing charges; time for service of notice of charge on respondent; filing of charge by Commission with State or local agency; seniority system"],[0,"(1) A charge under this section shall be filed within one hundred and eighty days after the alleged unlawful employment practice occurred and notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) shall be served upon the person against whom such charge is made within ten days thereafter, except that in a case of an unlawful employment practice with respect to which the person aggrieved has initially instituted proceedings with a State or local agency with authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, such charge shall be filed by or on behalf of the person aggrieved within three hundred days after the alleged unlawful employment practice occurred, or within thirty days after receiving notice that the State or local agency has terminated the proceedings under the State or local law, whichever is earlier, and a copy of such charge shall be filed by the Commission with the State or local agency."],[0,"(2) For purposes of this section, an unlawful employment practice occurs, with respect to a seniority system that has been adopted for an intentionally discriminatory purpose in violation of this subchapter (whether or not that discriminatory purpose is apparent on the face of the seniority provision), when the seniority system is adopted, when an individual becomes subject to the seniority system, or when a person aggrieved is injured by the application of the seniority system or provision of the system."],[0,"(3)(A) For purposes of this section, an unlawful employment practice occurs, with respect to discrimination in compensation in violation of this subchapter, when a discriminatory compensation decision or other practice is adopted, when an individual becomes subject to a discriminatory compensation decision or other practice, or when an individual is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(B) In addition to any relief authorized by section 1981a of this title, liability may accrue and an aggrieved person may obtain relief as provided in subsection (g)(1), including recovery of back pay for up to two years preceding the filing of the charge, where the unlawful employment practices that have occurred during the charge filing period are similar or related to unlawful employment practices with regard to discrimination in compensation that occurred outside the time for filing a charge."],[0,"(f) Civil action by Commission, Attorney General, or person aggrieved; preconditions; procedure; appointment of attorney; payment of fees, costs, or security; intervention; stay of Federal proceedings; action for appropriate temporary or preliminary relief pending final disposition of charge; jurisdiction and venue of United States courts; designation of judge to hear and determine case; assignment of case for hearing; expedition of case; appointment of master"],[0,"(1) If within thirty days after a charge is filed with the Commission or within thirty days after expiration of any period of reference under subsection (c) or (d), the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission may bring a civil action against any respondent not a government, governmental agency, or political subdivision named in the charge. In the case of a respondent which is a government, governmental agency, or political subdivision, if the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission shall take no further action and shall refer the case to the Attorney General who may bring a civil action against such respondent in the appropriate United States district court. The person or persons aggrieved shall have the right to intervene in a civil action brought by the Commission or the Attorney General in a case involving a government, governmental agency, or political subdivision. If a charge filed with the Commission pursuant to subsection (b), is dismissed by the Commission, or if within one hundred and eighty days from the filing of such charge or the expiration of any period of reference under subsection (c) or (d), whichever is later, the Commission has not filed a civil action under this section or the Attorney General has not filed a civil action in a case involving a government, governmental agency, or political subdivision, or the Commission has not entered into a conciliation agreement to which the person aggrieved is a party, the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, shall so notify the person aggrieved and within ninety days after the giving of such notice a civil action may be brought against the respondent named in the charge (A) by the person claiming to be aggrieved or (B) if such charge was filed by a member of the Commission, by any person whom the charge alleges was aggrieved by the alleged unlawful employment practice. Upon application by the complainant and in such circumstances as the court may deem just, the court may appoint an attorney for such complainant and may authorize the commencement of the action without the payment of fees, costs, or security. Upon timely application, the court may, in its discretion, permit the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, to intervene in such civil action upon certification that the case is of general public importance. Upon request, the court may, in its discretion, stay further proceedings for not more than sixty days pending the termination of State or local proceedings described in subsection (c) or (d) of this section or further efforts of the Commission to obtain voluntary compliance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-5?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–5. Enforcement provisions","tname":"The Public Health and Welfare","by":{"1":"37, 37, 31, 36, 37","2":"6"}},{"t":"case","label":"Alonso-Juarez v. Garland","cite":"80 F.4th 1039","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/80/1039/","sum":"Holding the thirty-day deadline in 8 U.S.C. § 1252(b)(1) to petition a U.S. court of appeals for review of an immigration judge’s order to be nonjurisdictional.","sumSrc":"brief:2","by":{"2":"15"}},{"t":"case","label":"Avia Dynamics, Inc. v. FAA","cite":"641 F.3d 515","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/641/515/","by":{"2":"15"}},{"t":"case","label":"Barnhart v. Thomas","cite":"540 U.S. 20","y":2003,"id":"2003/02-763","sc":1,"sum":"The Court held that the SSA's decision had been a reasonable interpretation of the statute and was therefore entitled to deference under Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc., 467 U.S. 837.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Bloate v. United States","cite":"559 U.S. 196","y":2010,"id":"2009/08-728","sc":1,"sum":"The Court held that the time granted to prepare pretrial motions is not automatically granted exclusion from the Speedy Trial Act's 70-day time limit.","sumSrc":"Oyez","by":{"2":"18–19"}},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Balt.","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"op":1,"sum":"Where defendant energy companies premised 28 U. S. C. §1447(d) removal in part on the federal officer removal statute, §1442, the Fourth Circuit erred in holding that it lacked jurisdiction to consider all grounds for removal rejected by the District Court.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"6"}},{"t":"case","label":"Clean Water Action Council of N.E. Wisc., Inc. v. EPA","cite":"765 F.3d 749","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/765/749/","sum":"Holding the deadline in 42 U.S.C. § 7607(b) to seek review of EPA regulations directly in U.S. courts of appeals to be nonjurisdictional.","sumSrc":"brief:2","by":{"2":"15"}},{"t":"case","label":"Corbett v. TSA","cite":"767 F.3d 1171","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/767/1171/","sum":"Holding the deadline in 49 U.S.C. § 46110(a) for seeking review of certain TSA orders in a U.S. court of appeals to be nonjurisdictional.","sumSrc":"brief:2","by":{"2":"15"}},{"t":"case","label":"Davis v. Mich. Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Eberhart v. United States","cite":"546 U.S. 12","y":2005,"id":"2005/04-9949","sc":1,"sum":"The Court held that Federal Rule of Criminal Procedure 33, which creates a seven-day limit for filing a motion for a new trial that is not based on newly discovered evidence, was not a jurisdictional rule but rather a claim-processing one.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"sum":"The Court stated that the Eighth Circuit could not order the district court to increase Greenlaw's sentence without a request from the government to do so. The Court pointed to several of its precedents for the rule that a remedy in favor the appellee, in this case the government, can only be justified if the appellee brings a cross-appeal.","sumSrc":"Oyez","by":{"2":"17–18"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"op":1,"sum":"The Court held that Kontrick lost the right to invoke Rule 4004's time limitation because he did so after the bankruptcy court reached the merits of Ryan's objection. The Court rejected Kontrick's claim that Rule 4004 is \"jurisdictional\" and that it trumps other considerations whenever raised in proceedings.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"McWhorter v. FAA","cite":"88 F.4th 1317","y":2023,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/88/1317/","sum":"Holding the deadline in 49 U.S.C. § 1153(b)(1) to appeal a decision of the National Transportation Safety Board to a U.S. court of appeals to be nonjurisdictional.","sumSrc":"brief:2","by":{"2":"14–15"}},{"t":"case","label":"Nat. Res. Def. Council v. NHTSA","cite":"894 F.3d 95","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/894/95/","sum":"Holding the deadline in 49 U.S.C. § 32909(b) to petition a U.S. courts of appeals for review of a final Traffic Safety Administration rule to be nonjurisdictional and subject to equitable tolling.","sumSrc":"brief:2","by":{"2":"15, 20"}},{"t":"case","label":"Sprietsma v. Mercury Marine","cite":"537 U.S. 51","y":2002,"id":"2002/01-706","sc":1,"sum":"The Court held 8-0 that neither the text nor the intent of the FBSA preempts Sprietsma's common law claims, either explicitly or implicitly.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"sum":"The Court found that a police department's placement of a GPS tracking device on a man's Jeep without his knowledge was an illegal search under the Fourth Amendment.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"2":"7, 15"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(b)"],"by":{"2":"15"}},{"t":"usc","label":"49 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/49/1153","subs":["(b)(1)"],"by":{"2":"15"}},{"t":"usc","label":"49 U.S.C. § 32909","url":"https://www.law.cornell.edu/uscode/text/49/32909","subs":["(b)"],"by":{"2":"15"}},{"t":"usc","label":"49 U.S.C. § 46110","url":"https://www.law.cornell.edu/uscode/text/49/46110","subs":["(a)"],"by":{"2":"15–16"}},{"t":"rule","label":"Fed. R. App. P. 26","url":"https://www.law.cornell.edu/rules/frap/rule_26","subs":["(b)"],"by":{"2":"19–20"}}]};